PROJ = "/home/user/pagoda"


def store(**kw) -> NoteStore:
    d = tempfile.mkdtemp(prefix="mem-")
    return NoteStore(d, settings=lambda: {"dedupe_threshold": 0.6}, **kw)


def add(st, title, body=None, scope="user", kind="gotcha", user="owner", **kw):
    body = body if body is not None else f"The fact: {title}, as the test wrote it."
    return st.write(user, {"op": "add", "scope": scope, "kind": kind, "title": title,
                           "body": body, **{k: v for k, v in kw.items()
                                            if k in ("tags", "verify_by")}},
                    writer=kw.get("writer", "qwen-inline"), project=kw.get("project", PROJ),
                    session=kw.get("session", "c:ses-1"), request_id="req-1",
                    from_user=kw.get("from_user", True))


def refused(fn, why):
    try:
        fn()
    except Refused as exc:
        assert exc.why == why, (exc.why, why, str(exc))
        return str(exc)
    raise AssertionError(f"not refused ({why})")


# ------------------------------------------------------------------------------ the store
def test_note_format():
    n = notes_mod.Note(id="0123456789ab", title="the build needs node 20", kind="gotcha",
                       scope="project", project=PROJ, status="provisional", writer="qwen-inline",
                       tags=["build", "node"], created="2026-10-05T01:00:00Z",
                       updated="2026-10-05T01:00:00Z", body="Line one.\n\nLine two.",
                       changelog=["2026-10-05 01:00 created by qwen-inline"])
    text = n.render()
    m = notes_mod.Note.parse(text, "/x.md")
    assert m.full() == n.full(), (m.full(), n.full())
    assert text.startswith("---\nid: 0123456789ab\n") and "## Changelog" in text
    assert notes_mod.Note.parse("---\ntitle: x\n---\nbody") is None


def test_add_and_scopes():
    st = store()
    r = add(st, "Answers in German for personal notes", kind="rule")
    n = st.get("owner", r["id"])
    assert n.status == "provisional" and n.writer == "qwen-inline" and n.scope == "user"
    assert n.path.startswith(os.path.join(st.dir, "owner", "user")), n.path
    assert stat.S_IMODE(os.stat(n.path).st_mode) == 0o600
    p = add(st, "the summer scene differs because offerings recolour", scope="project")
    s = add(st, "the branch is tandem-mem, do not touch dist", scope="session",
            kind="program_state")
    assert st.get("owner", p["id"]).project == PROJ
    assert "/projects/pagoda-" in st.get("owner", p["id"]).path
    assert "/sessions/c-ses-1/" in st.get("owner", s["id"]).path
    # SRV-277: no working directory (an Open WebUI chat): the project note lands at user scope
    q = add(st, "no project here", scope="project", project=None)
    assert q["scope"] == "user" and q["rescoped"] == "project", q
    assert "/owner/user/" in st.get("owner", q["id"]).path
    refused(lambda: add(st, "no session here", scope="session", session=None), "no_session")
    refused(lambda: add(st, "x", user="../etc"), "no_user")
    refused(lambda: add(st, "bad kind", kind="poem"), "schema")
    st.nightly()
    idx = open(os.path.join(st.dir, "owner", "INDEX.md")).read()
    assert r["id"] in idx and p["id"] in idx and s["id"] in idx, idx


def test_dedupe_to_revision():
    st = store()
    a = add(st, "The tests run with `make check`", body="Run make check in the root; it "
            "builds and runs the unit tests.", scope="project", kind="runbook")
    b = add(st, "the tests run with make check!", body="make check runs the unit tests after "
            "the build, from the project root.", scope="project", kind="runbook")
    assert b["id"] == a["id"] and b.get("revised"), b
    n = st.get("owner", a["id"])
    assert "after the build" in n.body and len(n.changelog) == 2, n.changelog
    revs = st.revisions("owner", a["id"])
    assert len(revs) == 1 and "builds and runs" in revs[0]["body"], revs
    # a near copy under a new title
    c = add(st, "How to check the project", body="make check runs the unit tests after the "
            "build, from the project root.", scope="project", kind="runbook")
    assert c["id"] == a["id"] and c.get("revised"), c
    # the same title in another scope is another note
    d = add(st, "the tests run with make check", scope="user", kind="runbook")
    assert d["id"] != a["id"]
    # a different fact stays apart
    e = add(st, "the dev server listens on port 5173", body="vite serves on 5173 unless the "
            "port is taken.", scope="project", kind="reference")
    assert e["id"] != a["id"]


def test_caps():
    st = store()
    refused(lambda: add(st, "t" * 121), "cap")
    refused(lambda: add(st, "long body", body="word " * 401), "cap")
    refused(lambda: add(st, "empty", body="  "), "schema")
    for i in range(notes_mod.CAPS["session_notes"]):
        add(st, f"step {i} of the session plan is distinct {i * 7919}", body=f"Unique fact "
            f"number {i} alpha{i} beta{i * 3} gamma{i * 11}.", scope="session",
            kind="program_state")
    refused(lambda: add(st, "one more session note zeta", body="omega psi chi", scope="session",
                        kind="program_state"), "cap")
    assert len(add(st, "t" * 120)["title"]) == 120


def test_secrets():
    st = store()
    key = "ghp_" + "A1b2C3d4" * 5
    r = add(st, "the deploy token", body=f"The deploy script reads GITHUB_TOKEN={key} from the "
            "environment of the CI runner, never from a file in the repository.")
    n = st.get("owner", r["id"])
    assert key not in open(n.path).read() and "[redacted:" in n.body
    assert r["redacted"], r
    refused(lambda: add(st, "just a key", body=f"token {key}"), "secret")


def test_rules_in_code():
    st = store()
    refused(lambda: add(st, "always use tabs", kind="rule", from_user=False), "rule_from_tool")
    add(st, "the project uses tabs", kind="rule", scope="project", from_user=False)  # project ok
    refused(lambda: st.write("owner", {"op": "update", "id": "ffffffffffff", "title": "x",
                                       "body": "y y y"}, writer="qwen-inline"), "unknown_id")
    s = add(st, "a session fact for ses-1 only", scope="session", kind="reference")
    refused(lambda: st.write("owner", {"op": "archive", "id": s["id"], "reason": "x"},
                             writer="qwen-inline", project=PROJ, session="c:other"),
            "unknown_id")
    r = add(st, "short answers please", kind="rule")
    st.set_status("owner", r["id"], "ratified")
    st.set_status("owner", r["id"], pinned=True)
    assert st.get("owner", r["id"]).pinned
    st.write("owner", {"op": "update", "id": r["id"], "title": "short answers please",
                       "body": "Keep answers under five sentences unless asked."},
             writer="qwen-inline", project=PROJ, session="c:ses-1")
    n = st.get("owner", r["id"])
    assert n.status == "provisional" and n.revisions == 1, (n.status, n.revisions)
    g = add(st, "a gotcha cannot be pinned", kind="gotcha")
    st.set_status("owner", g["id"], "ratified")
    refused(lambda: st.set_status("owner", g["id"], pinned=True), "schema")


def test_search():
    st = store()
    add(st, "pagoda checker gate a wants the summer scene close", body="The checker compares "
        "the summer scene within 1.0 of night 1.", scope="user", kind="reference")
    p = add(st, "pagoda checker gate a wants the summer scene close", body="The checker "
            "compares the summer scene within 1.0 of night 1.", scope="project",
            kind="reference")
    s = add(st, "pagoda checker gate a wants the summer scene close", body="The checker "
            "compares the summer scene within 1.0 of night 1.", scope="session",
            kind="reference")
    hits = st.search("owner", "summer scene checker", project=PROJ, session="c:ses-1", k=5)
    assert [n.id for n, _ in hits][:2] == [s["id"], p["id"]], [(n.scope, sc) for n, sc in hits]
    other = st.search("owner", "summer scene checker", project="/home/user/other",
                      session="c:ses-2", k=5)
    assert [n.scope for n, _ in other] == ["user"], other
    st.archive("owner", s["id"], "test")
    assert s["id"] not in [n.id for n, _ in st.search("owner", "summer", project=PROJ,
                                                     session="c:ses-1")]
    old = add(st, "the release is at rc4 waiting on the gate", kind="program_state",
              verify_by="2020-01-01", scope="user")
    assert old["id"] not in [n.id for n, _ in st.search("owner", "release rc4 gate")]
    assert st.search("nobody", "summer") == []


def test_archive_nightly_export():
    st = store()
    a = add(st, "a fact to archive later", kind="reference")
    b = add(st, "another fact to delete now", kind="reference")
    st.archive("owner", a["id"], "wrong")
    assert st.get("owner", a["id"]) is None and st.archived("owner")[0].id == a["id"]
    assert st.delete("owner", b["id"]) and st.get("owner", b["id"]) is None
    # an archive older than 30 days goes at night
    arch = st.archived("owner")[0]
    arch.archived = "2020-01-01T00:00:00Z"
    notes_mod._write_private(arch.path, arch.render())
    out = st.nightly()
    assert out["deleted"] == 1 and not st.archived("owner"), out
    z = zipfile.ZipFile(io.BytesIO(st.export("owner")))
    assert "owner/INDEX.md" in z.namelist(), z.namelist()
    assert st.delete_user("owner") and st.users() == []


def test_model_archive_of_a_ratified_note():
    st = store()
    r = add(st, "build requires node 20", scope="project",
            body="The project build needs node 20. Use nvm use 20 before building.")
    st.set_status("owner", r["id"], "ratified")
    op = {"op": "archive", "id": r["id"], "reason": "this project is pure Python"}
    out = st.write("owner", op, writer="qwen-inline", project=PROJ, session="c:ses-2")
    n = st.get("owner", r["id"])
    assert out["kept"] == "provisional" and n is not None and n.status == "provisional", out
    assert "asked to archive it (this project is pure Python)" in n.changelog[-1], n.changelog
    assert not st.archived("owner") and st.stats["doubted"] == 1
    # now provisional: the model's own call again
    out = st.write("owner", op, writer="qwen-inline", project=PROJ, session="c:ses-2")
    assert "kept" not in out and st.get("owner", r["id"]) is None
    assert st.archived("owner")[0].id == r["id"]
    # through Memory.take: the block is taken, no "forgot" line, the journal says kept
    p = add(st, "the tests run with pytest -q", scope="project")
    st.set_status("owner", p["id"], "ratified")
    j, ui = Journal(), UI()
    mem = memory_mod.Memory(st, j)
    ctx = {"mode": "on", "user": "owner", "project": PROJ, "session": "c:ses-3",
           "from_user": True, "request_id": "r9", "writer": "qwen-inline", "written": []}
    block = f'<tandem_memory op="archive" id="{p["id"]}" reason="no tests here">\n</tandem_memory>'
    assert mem.take(ctx, block, ui) is None and ui.lines == [], ui.lines
    assert ctx["written"][0]["kept"] == "provisional" and st.get("owner", p["id"]) is not None
    assert j.rows[-1][2]["detail"]["kept"] == "provisional"


# ------------------------------------------------------------------------------ the block
BLOCK = ('<tandem_memory op="add" scope="project" kind="gotcha">\n'
         'title: offerings recolour by season\ntags: pagoda, checker\n\n'
         'Gate (a) wants the summer scene within 1.0 of night 1.\n</tandem_memory>')


def test_block_parse():
    op = memblock.parse(BLOCK)
    assert op == {"op": "add", "scope": "project", "kind": "gotcha",
                  "title": "offerings recolour by season", "tags": "pagoda, checker",
                  "body": "Gate (a) wants the summer scene within 1.0 of night 1."}, op
    op = memblock.parse("<tandem_memory>\nscope: user\nkind: rule\ntitle: tabs\n\nUse tabs.\n"
                        "</tandem_memory>")
    assert op["op"] == "add" and op["scope"] == "user" and op["body"] == "Use tabs."
    op = memblock.parse("<tandem_memory op='archive' id=0123456789ab reason=\"wrong\">"
                        "</tandem_memory>")
    assert op["id"] == "0123456789ab" and op["reason"] == "wrong"
    for bad, why in (("<tandem_memory op=\"burn\">x</tandem_memory>", "schema"),
                     ("<tandem_memory op=\"update\">x</tandem_memory>", "schema"),
                     ("<tandem_memory op=\"propose\">x</tandem_memory>", "schema")):
        try:
            memblock.parse(bad)
            raise AssertionError(bad)
        except memblock.BlockError as exc:
            assert exc.why == why


def feed_all(f, text, step):
    out = [f.feed(text[i:i + step]) for i in range(0, len(text), step)]
    return "".join(out) + f.finish()


def test_stream_filter():
    text = "Done, the gate passes now.\n\n" + BLOCK + "\n"
    for step in (1, 2, 3, 7, 50, 1000):
        got = []
        f = memblock.MemFilter(lambda raw: got.append(raw))
        assert feed_all(f, text, step) == "Done, the gate passes now.\n\n\n", (step,)
        assert got == [BLOCK] and f.taken == [BLOCK], step
    # refused: hidden all the same (SRV-277), the reason kept
    f = memblock.MemFilter(lambda raw: "cap")
    assert feed_all(f, "a " + BLOCK, 5) == "a " and f.failed == ["cap"]
    assert f.hidden == [BLOCK] and f.taken == [] and f.shown == []
    # unclosed
    f = memblock.MemFilter(lambda raw: None)
    half = BLOCK[:60]
    assert feed_all(f, "x " + half, 4) == "x " + half and f.failed == ["unclosed"]
    # five blocks: the fifth is not written, and hidden
    f = memblock.MemFilter(lambda raw: None)
    out = feed_all(f, (BLOCK + "\n") * 5, 9)
    assert out == "\n" * 5 and f.failed == ["too_many"], (out, f.failed)
    assert len(f.taken) == 4 and len(f.hidden) == 5
    # not ours
    f = memblock.MemFilter(lambda raw: None)
    s = "see <tandem_memoryx> and <tandem_mem"
    assert feed_all(f, s, 3) == s
    # too long but closed within the hold: not written, hidden
    f = memblock.MemFilter(lambda raw: None)
    long = '<tandem_memory op="add">\n' + "y" * 2100 + "</tandem_memory>"
    assert feed_all(f, long, 100) == "" and f.failed == ["too_long"] and f.hidden == [long]
    # still open past the hold limit: not a note any more, out as text
    f = memblock.MemFilter(lambda raw: None)
    huge = '<tandem_memory op="add">\n' + "y" * (memblock.HOLD_CHARS + 100) + "</tandem_memory>"
    assert feed_all(f, huge, 100) == huge and f.failed == ["too_long"] and f.shown == ["too_long"]
    assert f.hidden == []
    # the non-streamed strip
    rest, found = memblock.strip_blocks("a " + BLOCK + " b")
    assert rest == "a  b" and found == [BLOCK]


class CharTok:
    """One token a character, except the pieces in `merges` (a token holding more)."""

    def __init__(self, merges=()):
        self.merges = list(merges)
        self.vocab: dict[str, int] = {}
        self.inv: dict[int, str] = {}

    def encode(self, text):
        out, i = [], 0
        while i < len(text):
            for m in self.merges:
                if text.startswith(m, i):
                    piece = m
                    break
            else:
                piece = text[i]
            if piece not in self.vocab:
                self.vocab[piece] = len(self.vocab) + 1
                self.inv[self.vocab[piece]] = piece
            out.append(self.vocab[piece])
            i += len(piece)
        return out

    def decode(self, ids):
        return "".join(self.inv[i] for i in ids)


def test_token_spans():
    tok = CharTok(merges=["\n\n", "<tandem", "_memory"])
    text = "Done.\n\n" + BLOCK + "\n\nAnd more."
    ids = tok.encode(text)
    spans, bad = memblock.token_spans(ids, tok.decode, [BLOCK])
    assert bad == 0 and len(spans) == 1
    k0, k1 = spans[0]
    assert tok.decode(ids[k0:k1]) == BLOCK, tok.decode(ids[k0:k1])
    # an edge inside a token that holds visible text: not recorded
    tok2 = CharTok(merges=[".<tandem"])
    ids2 = tok2.encode("Done." + BLOCK)
    spans2, bad2 = memblock.token_spans(ids2, tok2.decode, [BLOCK])
    assert spans2 == [] and bad2 == 1


# ------------------------------------------------------------------------------ the router
TOOLS = [{"type": "function", "function": {"name": "bash", "description": "run a command",
                                           "parameters": {"type": "object", "properties": {
                                               "command": {"type": "string"}}}}}]
SYSTEM = f"You are opencode.\nWorking directory: {PROJ}\nPlatform: linux"


def conductor(mode="on", intent="off", decider=None):
    from server.conductor.hook import Conductor

    class Fake:
        def __init__(self, fn):
            self.fn = fn

        def choice(self, text, question, options, max_chars=None):
            from server.conductor.classify import Answer
            got = self.fn(text, options)
            if isinstance(got, str):
                return Answer("decider", error=got)
            return Answer("decider", got[0], got[1], {})

        def state_chars(self):
            return 4000

    fakes = {"decider": Fake(decider or (lambda t, o: ("code_edit", 0.95)
                                         if "code_edit" in o else ("no", 0.9))),
             "qwen": Fake(lambda t, o: ("code_edit", 0.95) if "code_edit" in o
                          else "qwen_unreachable")}
    cond = Conductor(tempfile.mkdtemp(prefix="cond-"), state={}, journal=False,
                     factory=lambda kind, role, timeout: fakes[kind])
    v, prof = cond.store.get("profiles", "coding")
    if mode is not None:
        prof = dict(prof, memory=mode)
    cond.store.put("profiles", "coding", prof, note="test", base=v, author="test")
    v, st = cond.store.get("settings")
    st = json.loads(json.dumps(st))
    st.setdefault("memory", {})["notes"] = {"intent": intent}
    cond.store.put("settings", None, st, note="test", base=v, author="test")
    if decider is not None:
        v, roles = cond.store.get("roles")
        roles = json.loads(json.dumps(roles))
        roles["decider"] = dict(roles.get("decider") or {}, mode="on", endpoint="self")
        cond.store.put("roles", None, roles, note="test", base=v, author="test")
    return cond


def msgs(*turns):
    out = [{"role": "system", "content": SYSTEM}]
    for t in turns:
        out.append(t if isinstance(t, dict) else {"role": "user", "content": t})
    return out


def plan_of(cond, messages, user="owner", sid="ses-1"):
    return cond.plan({"model": "TandemLLM", "messages": messages, "tools": TOOLS},
                     {"x-session-id": sid}, client_kind="opencode", request_id="r",
                     chat=True, user=user)


def kinds(plan):
    return [p["kind"] for x in plan.extras for p in x["parts"]]


def test_router_attach():
    # off: nothing
    cond = conductor(mode=None)
    p = plan_of(cond, msgs("How do I check the summer scene?"))
    assert p.memory is None and not [k for k in kinds(p) if k.startswith("memory")]
    assert "memory" not in p.row["extra"]
    # shadow: the card only
    cond = conductor(mode="shadow")
    cond.notes.write("owner", {"op": "add", "scope": "project", "kind": "gotcha",
                               "title": "summer scene checker gate", "body": "The summer "
                               "scene must stay within 1.0 of night 1."},
                     writer="human", project=PROJ)
    p = plan_of(cond, msgs("How do I check the summer scene?"))
    assert [k for k in kinds(p) if k.startswith("memory")] == ["memory_card"], kinds(p)
    assert p.memory["mode"] == "shadow" and p.memory["project"] == PROJ
    # on: card, index, bodies
    cond = conductor(mode="on")
    nid = cond.notes.write("owner", {"op": "add", "scope": "project", "kind": "gotcha",
                                     "title": "summer scene checker gate", "body": "The summer "
                                     "scene must stay within 1.0 of night 1."},
                           writer="human", project=PROJ)["id"]
    p = plan_of(cond, msgs("How do I check the summer scene?"))
    ks = kinds(p)
    assert "memory_card" in ks and "memory_index" in ks and "memory" in ks, ks
    idx = next(x for x in p.extras if x["parts"][0]["kind"] == "memory_index")
    assert nid in idx["text"] and "/v1/memory/" in idx["text"]
    bodies = next(x for x in p.extras if x["parts"][0]["kind"] == "memory")
    assert "within 1.0 of night 1" in bodies["text"] and bodies["parts"][0]["name"] == nid
    assert p.row["extra"]["memory"]["bodies"][0]["id"] == nid
    # a tool turn: no bodies
    p = plan_of(cond, msgs("How do I check the summer scene?",
                           {"role": "assistant", "content": "", "tool_calls": [
                               {"id": "c1", "type": "function", "function": {
                                   "name": "bash", "arguments": "{\"command\": \"ls\"}"}}]},
                           {"role": "tool", "tool_call_id": "c1", "content": "a b"}))
    assert "memory" not in kinds(p) and p.memory["from_user"] is False
    # no user: nothing at all
    p = plan_of(cond, msgs("How do I check the summer scene?"), user=None)
    assert p.memory is None and not [k for k in kinds(p) if k.startswith("memory")]
    # the intent question, shadow: journaled, no skill
    cond = conductor(mode="on", intent="shadow",
                     decider=lambda t, o: ("code_edit", 0.95) if "code_edit" in o
                     else ("yes", 0.92))
    p = plan_of(cond, msgs("Remember that I want short answers from now on."))
    assert p.row["extra"]["memory"]["intent"]["answer"] == "yes", p.row["extra"]["memory"]
    assert "memory_skill" not in kinds(p) and p.row["shadow"].get("memory_skill") == "memory"
    cond = conductor(mode="on", intent="on",
                     decider=lambda t, o: ("code_edit", 0.95) if "code_edit" in o
                     else ("yes", 0.92))
    p = plan_of(cond, msgs("Remember that I want short answers from now on."))
    assert "memory_skill" in kinds(p), kinds(p)
    skill = next(x for x in p.extras if x["parts"][0]["kind"] == "memory_skill")
    assert "<tandem_memory" in skill["text"] and "{tandem_url}" not in skill["text"]


class UI:
    def __init__(self):
        self.lines = []

    def add(self, kind, **facts):
        self.lines.append((kind, facts))


class Journal:
    def __init__(self):
        self.rows = []

    def note(self, kind, task, **kw):
        self.rows.append((kind, task, kw))
        return {}


def test_take():
    st = store()
    j = Journal()
    mem = memory_mod.Memory(st, j)
    ui = UI()
    ctx = {"mode": "on", "user": "owner", "project": PROJ, "session": "c:ses-1",
           "from_user": True, "request_id": "r1", "writer": "qwen-inline", "written": []}
    f = mem.filter(ctx, ui)
    out = feed_all(f, "Noted.\n\n" + BLOCK, 11)
    assert out == "Noted.\n\n" and ui.lines == [("remembered", {
        "title": "offerings recolour by season"})], (out, ui.lines)
    assert ctx["written"][0]["op"] == "add" and ctx["written"][0]["scope"] == "project"
    assert st.notes("owner")[0].title == "offerings recolour by season"
    kind, task, kw = j.rows[0]
    assert (kind, task) == ("memory_notes", "write") and "title" not in json.dumps(kw["detail"])
    assert "offerings" not in json.dumps(kw)
    # a refused block is hidden too (SRV-277)
    bad = BLOCK.replace('kind="gotcha"', 'kind="poem"')
    f = mem.filter(ctx, ui)
    assert feed_all(f, bad, 13) == "" and f.failed == ["schema"] and f.hidden == [bad]
    assert j.rows[-1][2]["decision"] == "schema"
    # off: no filter
    assert mem.filter({"mode": "off"}) is None and mem.filter(None) is None


# ------------------------------------------------------------------------------ the routes
class Handler:
    def __init__(self, path, stok=None, sess=None, body=b""):
        self.path, self._stok, self._sess = path, stok, sess
        self.out = None
        self.headers = {}
        self.status = None
        self.raw = None

    def _json(self, status, payload, extra_headers=()):
        self.status, self.out = status, payload

    def _allowed(self, route):
        return True

    def _peer(self):
        return "127.0.0.1"

    def send_response(self, status):
        self.status = status

    def send_header(self, k, v):
        pass

    def end_headers(self):
        pass

    @property
    def wfile(self):
        h = self

        class W:
            def write(self, data):
                h.raw = data
        return W()


def test_model_routes():
    from server import memory_api
    cond = conductor(mode="on")
    p = plan_of(cond, msgs("How do I check the summer scene?"))
    key = p.session.key
    h = Handler("/v1/memory/search?q=summer")
    memory_api.handle(h, cond, "GET", None)
    assert h.status == 403, h.out
    h = Handler("/v1/memory/search?q=summer", stok="tok", sess="c:unknown")
    memory_api.handle(h, cond, "GET", None)
    assert h.status == 403
    h = Handler("/v1/memory", stok="tok", sess=key)
    memory_api.handle(h, cond, "POST", {"op": "add", "scope": "project", "kind": "runbook",
                                        "title": "run the checker with make check",
                                        "body": "make check runs the gates a to d."})
    assert h.status == 200 and h.out["op"] == "add", h.out
    nid = h.out["id"]
    h = Handler("/v1/memory/search?q=checker+gates&k=3", stok="tok", sess=key)
    memory_api.handle(h, cond, "GET", None)
    assert h.status == 200 and h.out[0]["id"] == nid, h.out
    h = Handler(f"/v1/memory/{nid}", stok="tok", sess=key)
    memory_api.handle(h, cond, "GET", None)
    assert h.status == 200 and h.out["body"].startswith("make check"), h.out
    h = Handler("/v1/memory", stok="tok", sess=key)
    memory_api.handle(h, cond, "POST", {"op": "add", "scope": "user", "kind": "rule",
                                        "title": "x rule", "body": "a rule from a script"})
    assert h.status == 422 and h.out["error"]["type"] == "rule_from_tool", h.out
    h = Handler("/v1/memory", stok="tok", sess=key)
    memory_api.handle(h, cond, "GET", None)
    assert h.status == 200 and h.out["scopes"][0]["scope"] == "project", h.out


def admin(cond, method, path, body=None):
    from server.conductor import routes
    h = Handler(path)
    routes.handle(h, cond, method, body or {}, auth=None)
    return h


def test_admin_routes():
    cond = conductor(mode="on")
    r = cond.notes.write("owner", {"op": "add", "scope": "user", "kind": "rule",
                                   "title": "short answers", "body": "Keep answers short."},
                         writer="qwen-inline")
    nid = r["id"]
    h = admin(cond, "GET", "/v1/conductor/memory/notes")
    assert h.status == 200 and h.out["notes"][0]["id"] == nid and h.out["tree"][0]["count"] == 1
    assert "body" not in h.out["notes"][0]
    h = admin(cond, "PUT", f"/v1/conductor/memory/notes/{nid}",
              {"body": "Keep answers under five sentences."})
    assert h.out["note"]["status"] == "ratified" and h.out["note"]["writer"] == "human", h.out
    h = admin(cond, "PATCH", f"/v1/conductor/memory/notes/{nid}", {"pinned": True})
    assert h.out["note"]["pinned"] is True
    h = admin(cond, "GET", f"/v1/conductor/memory/notes/{nid}")
    assert len(h.out["revisions"]) == 1 and "Keep answers short." == \
        h.out["revisions"][0]["body"], h.out["revisions"]
    h = admin(cond, "GET", "/v1/conductor/memory/notes/search?q=answers")
    assert h.out["hits"][0]["id"] == nid and h.out["hits"][0]["score"] > 0
    h = admin(cond, "GET", "/v1/conductor/memory/notes/export")
    assert h.status == 200 and h.raw[:2] == b"PK"
    h = admin(cond, "POST", f"/v1/conductor/memory/notes/{nid}/archive", {"reason": "old"})
    assert h.status == 200 and cond.notes.get("owner", nid) is None
    h = admin(cond, "GET", f"/v1/conductor/memory/notes/{nid}")
    assert h.out["note"]["archived"], h.out
    h = admin(cond, "DELETE", f"/v1/conductor/memory/notes/{nid}")
    assert h.status == 200
    h = admin(cond, "DELETE", f"/v1/conductor/memory/notes/{nid}")
    assert h.status == 404
    h = admin(cond, "DELETE", "/v1/conductor/memory/notes/users/owner", {})
    assert h.status == 400
    h = admin(cond, "DELETE", "/v1/conductor/memory/notes/users/owner", {"confirm": "owner"})
    assert h.status == 200, h.out
    h = admin(cond, "GET", "/v1/conductor/memory/notes?user=../x")
    assert h.status == 400


def test_proposals():
    cond = conductor(mode="on")
    ctx = {"mode": "on", "user": "owner", "project": PROJ, "session": "c:ses-1",
           "from_user": True, "request_id": "r1", "writer": "qwen-inline", "written": []}
    ui = UI()
    block = ('<tandem_memory op="propose" kind="package" name="ui-design" mode="append">\n'
             'title: a Sources section\nreason: the last session searched for references\n\n'
             '## Sources\nSearch "material design color system" for palettes.\n</tandem_memory>')
    f = cond.memory.filter(ctx, ui)
    assert feed_all(f, "Done.\n\n" + block, 9) == "Done.\n\n" and f.failed == [], f.failed
    assert ui.lines == [("proposed", {"title": "ui-design"})], ui.lines
    v0, doc0 = cond.store.get("packages")
    h = admin(cond, "GET", "/v1/conductor/memory/proposals")
    assert [(p["name"], p["n"], p["status"]) for p in h.out["proposals"]] == [("ui-design", 1,
                                                                               "open")]
    h = admin(cond, "GET", "/v1/conductor/memory/proposals/ui-design/1")
    p = h.out["proposal"]
    assert p["applies"] and p["evidence_word"] == "no evidence" and p["live"] and \
        p["proposed"].endswith("for palettes.") and p["proposed"].startswith(p["live"].rstrip())
    assert cond.store.get("packages")[0] == v0            # nothing applied without a click
    h = admin(cond, "POST", "/v1/conductor/memory/proposals/ui-design/1/apply")
    assert h.status == 200 and h.out["version"] == v0 + 1, h.out
    v1, doc1 = cond.store.get("packages")
    assert doc1["packages"]["ui-design"]["body"].endswith("for palettes.")
    h = admin(cond, "POST", "/v1/conductor/memory/proposals/ui-design/1/apply")
    assert h.status == 409
    # the old version restores the old text
    old = cond.store.version("packages", None, v0) if hasattr(cond.store, "version") else None
    if old is not None:
        assert "for palettes." not in (old.get("packages", {}).get("ui-design", {}).get("body") or
                                       "")
    # a replacement of a text that changed since is refused; an unknown package too
    cond.memory.take(ctx, '<tandem_memory op="propose" name="ui-design">\ntitle: shorter\n\n'
                          '# UI design\nShort rules.\n</tandem_memory>')
    v, doc = cond.store.get("packages")
    pk = dict(doc["packages"]["ui-design"], body=doc["packages"]["ui-design"]["body"] + "\nX")
    cond.store.put("packages", None, dict(doc, packages=dict(doc["packages"],
                                                               **{"ui-design": pk})),
                   note="a human edit", author="test", base=v)
    h = admin(cond, "POST", "/v1/conductor/memory/proposals/ui-design/2/apply")
    assert h.status == 409 and h.out["error"]["type"] == "stale", h.out
    h = admin(cond, "POST", "/v1/conductor/memory/proposals/ui-design/2/reject",
              {"reason": "too short"})
    assert h.out["status"] == "rejected"
    assert cond.proposals.get("ui-design", 2)["rejected_reason"] == "too short"
    why = cond.memory.take(ctx, '<tandem_memory op="propose" name="no-such">\ntitle: x\n\n'
                                'text\n</tandem_memory>')
    assert why == "unknown_package", why


def test_srv277_owui_block_never_shown():
    """CACHE1's W05 (0.4.3-test, 2026-10-07 22:06): the model wrote a project-scoped reference
    note in an Open WebUI chat; the store refused it (no_project) and the whole block reached
    the user as text."""
    st = store()
    j = Journal()
    mem = memory_mod.Memory(st, j)
    ui = UI()
    owui = {"mode": "on", "user": "owner", "project": None, "session": "c:owui-chat-1",
            "from_user": True, "request_id": "r-w05", "writer": "qwen-inline", "written": []}
    note = ('<tandem_memory op="add" scope="project" kind="reference">\n'
            'title: TandemLLM docs summary\n\nThe docs cover the engine, the conductor and the '
            'packages; Laya is the decision model.\n</tandem_memory>')
    answer = "Here is the summary of the docs.\n\n"
    for step in (1, 7, 64, 5000):
        f = mem.filter(dict(owui, written=[]), ui)
        out = feed_all(f, answer + note, step)
        assert out == answer and "<tandem_memory" not in out, (step, out)
        assert f.hidden == [note] and f.failed == [], (step, f.failed)
    n = [x for x in st.notes("owner") if x.title == "TandemLLM docs summary"]
    assert len(n) == 1 and n[0].scope == "user" and n[0].project is None, n
    rows = [kw for k, t, kw in j.rows if (k, t) == ("memory_notes", "write")]
    assert rows[0]["decision"] == "add" and rows[0]["detail"]["rescoped"] == "project", rows[0]
    assert ui.lines[0] == ("remembered", {"title": "TandemLLM docs summary"}), ui.lines
    # the same block again: a revision of that note, still hidden
    f = mem.filter(dict(owui, written=[]), ui)
    assert feed_all(f, answer + note, 9) == answer
    assert len([x for x in st.notes("owner") if x.title == "TandemLLM docs summary"]) == 1
    # refused blocks: hidden, the reason in the journal
    rule_from_tool = note.replace('scope="project" kind="reference"', 'scope="user" kind="rule"')
    for raw, why, ctx in ((note.replace('kind="reference"', 'kind="poem"'), "schema", owui),
                          (rule_from_tool, "rule_from_tool", dict(owui, from_user=False))):
        f = mem.filter(dict(ctx, written=[]), ui)
        assert feed_all(f, "Done.\n" + raw + "\nBye.", 5) == "Done.\n\nBye.", why
        assert f.failed == [why] and f.hidden == [raw], (why, f.failed)
        assert j.rows[-1][2]["decision"] == why
    # the hidden blocks are spans of whole tokens (the end alignment puts them back)
    tok = CharTok()
    text = "Done.\n" + note + "\nBye."
    ids = tok.encode(text)
    spans, bad = memblock.token_spans(ids, tok.decode, [note])
    assert bad == 0 and len(spans) == 1 and tok.decode(ids[spans[0][0]:spans[0][1]]).strip() \
        == note, (spans, bad)


